def first_missing_positive(nums):
    n = len(nums)
    # With n items the answer can only be 1 .. n + 1, so only the values 1 .. n matter. Park each of them in "its" slot: value v goes to index v - 1.
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            slot = nums[i] - 1                           # work out the slot first: nums[i] changes during the swap
            nums[i], nums[slot] = nums[slot], nums[i]
    # The first slot that does not hold its own number shows which number is missing.
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1
